import requests
import os
from urllib.parse import urlparse

def scarica_immagini(lista_url):
    """
    Scarica immagini da una lista di URL e le salva nella directory corrente.

    Args:
        lista_url (list): Una lista di URL delle immagini da scaricare.
    """

    if not lista_url:
        print("Nessun URL fornito per il download.")
        return

    print("Inizio download immagini...")

    count = 1

    for url in lista_url:
        try:
            response = requests.get(url, stream=True)
            response.raise_for_status() # Solleva un'eccezione per status code di errore (4xx o 5xx)

            parsed_url = urlparse(url)
            nome_file = str (count) + 'X' + os.path.basename(parsed_url.path)
            if not nome_file:
                nome_file = "immagine_senza_nome" + str(lista_url.index(url)) + ".jpg" # Nome di default se non si riesce a estrarre un nome dal URL
            nome_file = nome_file.split("?")[0] # Rimuove i parametri dalla stringa del nome file, se presenti

            percorso_file = os.path.join(".", nome_file) # Salva nella directory corrente

            with open(percorso_file, 'wb') as file_immagine:
                for chunk in response.iter_content(chunk_size=8192): # Scarica in chunks per gestire anche file grandi
                    file_immagine.write(chunk)
            count +=1
            print(f"Immagine scaricata con successo e salvata come: {nome_file}")

        except requests.exceptions.RequestException as e:
            print(f"Errore durante il download dell'immagine da {url}: {e}")
        except Exception as e:
            print(f"Errore inaspettato durante l'elaborazione di {url}: {e}")

    print("\nDownload di tutte le immagini completato.")

